    _same = [_q[0] for _q in U28_COPY if _q[6] == _r[6]]
    assert not _same or U53_FILES["Common/Items/SkyyGear/UT/%s.png" % _r[0]] != U28_FILES["Common/Items/SkyyGear/UT/%s.png" % _same[0]], "0.3.53 %s looks like %s" % (_r[0], _same)
