def block(start, stop):
    a = P.s.index(start)
    b = P.s.index(stop, a)
    assert P.s.count(start) == 1 and a < b
    return P.s[a:b]


def subst(t, pairs):
    for o, n in pairs:
        assert o in t, "subst anchor gone: " + o[:80]
        t = t.replace(o, n)
    return t


